#define EVOLUTION_LEARN_COUNT 253
#define MAX_EVOLUTION_MOVES 4
#define MAX_LEARNABLE_MOVES (MAX_LEARNSET_MOVES + MAX_EVOLUTION_MOVES)

static inline uint8_t evolutionMoveCount(int16_t dex) {
  uint8_t n = 0;
  for (uint16_t i = 0; i < EVOLUTION_LEARN_COUNT; i++)
    if (EVOLUTION_LEARN_TBL[i].dex == dex) n++;
  return n;
}

static inline MoveId evolutionMove(int16_t dex, uint8_t which) {
  for (uint16_t i = 0; i < EVOLUTION_LEARN_COUNT; i++) {
    if (EVOLUTION_LEARN_TBL[i].dex != dex) continue;
    if (!which--) return EVOLUTION_LEARN_TBL[i].move;
  }
  return MV_NONE;
}
